\set ON_ERROR_STOP on
CREATE SCHEMA IF NOT EXISTS phase3_lab;
CREATE TABLE IF NOT EXISTS phase3_lab.items (
    id integer PRIMARY KEY,
    payload text NOT NULL
);
INSERT INTO phase3_lab.items
SELECT i, repeat(md5(i::text), 8) FROM generate_series(1, 100000) AS g(i)
ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS phase3_lab.events (
    token text PRIMARY KEY,
    stage text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT clock_timestamp()
);
ANALYZE phase3_lab.items;
SELECT count(*), md5(string_agg(md5(id::text || payload), '' ORDER BY id))
FROM phase3_lab.items;
